INSERT INTO tests (title, status, owner_id, is_bank, is_sample) VALUES ('តេស្តបុរេ ថ្នាក់ទី៩ (ពីមេរៀនថ្នាក់ទី៨) — ៦០ នាទី', 'draft', (SELECT id FROM teachers WHERE role = 'owner' ORDER BY id LIMIT 1), 0, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES ((SELECT MAX(id) FROM tests WHERE title = 'តេស្តបុរេ ថ្នាក់ទី៩ (ពីមេរៀនថ្នាក់ទី៨) — ៦០ នាទី'), 1, 'គណនា \(x(3x+1)\) ៖', NULL, '["\\(3 x^{2} + 1\\)", "\\(3 x + 1\\)", "\\(4 x\\)", "\\(3 x^{2} + x\\)"]', 3, NULL, 2, 'mcq', '\(x(3x+1) = 3 x^{2} + x\)។', 'កន្សោមពីជគណិត', 'easy', 1, '8', 'កន្សោមពីជគណិត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES ((SELECT MAX(id) FROM tests WHERE title = 'តេស្តបុរេ ថ្នាក់ទី៩ (ពីមេរៀនថ្នាក់ទី៨) — ៦០ នាទី'), 2, 'ពង្រាត \((x+3)^{2}\) ៖', NULL, '["\\(x^{2} + 9\\)", "\\(x^{2} + 6 x + 6\\)", "\\(x^{2} + 3 x + 9\\)", "\\(x^{2} + 6 x + 9\\)"]', 3, NULL, 2, 'mcq', '\((x+3)^{2} = x^{2} + 6 x + 9\)។', 'កន្សោមពីជគណិត', 'medium', 1, '8', 'កន្សោមពីជគណិត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES ((SELECT MAX(id) FROM tests WHERE title = 'តេស្តបុរេ ថ្នាក់ទី៩ (ពីមេរៀនថ្នាក់ទី៨) — ៦០ នាទី'), 3, 'កន្សោមមួយណាមិនមែនជាកន្សោមសនិទាន?', NULL, '["\\(\\dfrac{a+b}{b}\\)", "\\(\\dfrac{x}{y}\\)", "\\(\\dfrac{1+x}{x^2-1}\\)", "\\(\\dfrac{x}{\\sqrt{y}}\\)"]', 3, NULL, 2, 'mcq', '\(\sqrt{y}\) ពុំមែនជាឯកធា ឬពហុធា។', 'កន្សោមសនិទាន', 'easy', 1, '8', 'កន្សោមសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES ((SELECT MAX(id) FROM tests WHERE title = 'តេស្តបុរេ ថ្នាក់ទី៩ (ពីមេរៀនថ្នាក់ទី៨) — ៦០ នាទី'), 4, 'សម្រួល \(\dfrac{3x^{2}+4x}{9x^{2}-16}\) ៖', NULL, '["\\(\\dfrac{3 x - 4}{x}\\)", "\\(\\dfrac{x}{3 x + 4}\\)", "\\(- \\dfrac{x}{3 x - 4}\\)", "\\(\\dfrac{x}{3 x - 4}\\)"]', 3, NULL, 2, 'mcq', 'ដាក់ជាផលគុណកត្តា រួចសម្រួល ៖ \(\dfrac{x}{3 x - 4}\)។', 'កន្សោមសនិទាន', 'medium', 1, '8', 'កន្សោមសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES ((SELECT MAX(id) FROM tests WHERE title = 'តេស្តបុរេ ថ្នាក់ទី៩ (ពីមេរៀនថ្នាក់ទី៨) — ៦០ នាទី'), 5, 'ត្រីកោណសមបាត \(ABC\) មានកំពូល \(A\) និងមុំកំពូល \(\angle A = 50^\circ\)។ រង្វាស់មុំបាត \(\angle B\) ស្មើ ៖', NULL, '["\\(70^\\circ\\)", "\\(50^\\circ\\)", "\\(60^\\circ\\)", "\\(65^\\circ\\)"]', 3, NULL, 2, 'mcq', '\(\angle B = \dfrac{180^\circ - 50^\circ}{2} = \dfrac{130^\circ}{2} = 65^\circ\)។', 'ការប្រៀបធៀបត្រីកោណ', 'medium', 1, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES ((SELECT MAX(id) FROM tests WHERE title = 'តេស្តបុរេ ថ្នាក់ទី៩ (ពីមេរៀនថ្នាក់ទី៨) — ៦០ នាទី'), 6, 'ចតុកោណស្មើជាប្រលេឡូក្រាមដែលមាន ៖', NULL, '["\\(\\text{ជ្រុងឈមមិនប៉ុនគ្នា}\\)", "\\(\\text{មុំទាំងបួនកែង}\\)", "\\(\\text{អង្កត់ទ្រូងប៉ុនគ្នា}\\)", "\\(\\text{ជ្រុងទាំងបួនមានប្រវែងប៉ុនគ្នា}\\)"]', 3, NULL, 2, 'mcq', 'ចតុកោណស្មើ (Rhombus) មានជ្រុងទាំងបួនប៉ុនគ្នា។', 'ចតុកោណ', 'easy', 1, '8', 'ចតុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES ((SELECT MAX(id) FROM tests WHERE title = 'តេស្តបុរេ ថ្នាក់ទី៩ (ពីមេរៀនថ្នាក់ទី៨) — ៦០ នាទី'), 7, 'ក្នុងប្រលេឡូក្រាមមួយ មុំតគ្នាពីរមានផលធៀប \(1 \colon 3\)។ រង្វាស់មុំតូចគឺ ៖', NULL, '["\\(45^\\circ\\)", "\\(40^\\circ\\)", "\\(60^\\circ\\)", "\\(30^\\circ\\)"]', 0, NULL, 2, 'mcq', '\(x + 3x = 180^\circ \Rightarrow 4x = 180^\circ \Rightarrow x = 45^\circ\)។', 'ចតុកោណ', 'medium', 1, '8', 'ចតុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES ((SELECT MAX(id) FROM tests WHERE title = 'តេស្តបុរេ ថ្នាក់ទី៩ (ពីមេរៀនថ្នាក់ទី៨) — ៦០ នាទី'), 8, 'ចំនួនច្រាសនៃ \(\dfrac{3}{7}\) គឺ៖', NULL, '["\\(-\\dfrac{7}{3}\\)", "\\(-\\dfrac{3}{7}\\)", "\\(\\dfrac{3}{7}\\)", "\\(\\dfrac{7}{3}\\)"]', 3, NULL, 2, 'mcq', '\(\dfrac{3}{7} \cdot \dfrac{7}{3} = 1\)។', 'ចំនួនសនិទាន', 'easy', 1, '8', 'ចំនួនសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES ((SELECT MAX(id) FROM tests WHERE title = 'តេស្តបុរេ ថ្នាក់ទី៩ (ពីមេរៀនថ្នាក់ទី៨) — ៦០ នាទី'), 9, 'គណនា \(\dfrac{4}{5} \div \dfrac{1}{10}\)៖', NULL, '["\\(\\dfrac{1}{8}\\)", "\\(8\\)", "\\(\\dfrac{2}{25}\\)", "\\(40\\)"]', 1, NULL, 2, 'mcq', '\(\dfrac{4}{5} \times 10 = 8\)។', 'ចំនួនសនិទាន', 'medium', 1, '8', 'ចំនួនសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES ((SELECT MAX(id) FROM tests WHERE title = 'តេស្តបុរេ ថ្នាក់ទី៩ (ពីមេរៀនថ្នាក់ទី៨) — ៦០ នាទី'), 10, 'ទំហំ \(y\) និង \(x\) សមាមាត្រច្រាស នោះទំនាក់ទំនងគឺ៖', NULL, '["\\(y = a - x\\)", "\\(y = ax\\)", "\\(xy = a\\)", "\\(\\dfrac{y}{x} = a\\)"]', 2, NULL, 2, 'mcq', 'សមាមាត្រច្រាស \(xy = a\) ឬ \(y = \dfrac{a}{x}\)។', 'ទំហំសមាមាត្រនិងភាគរយ', 'easy', 1, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES ((SELECT MAX(id) FROM tests WHERE title = 'តេស្តបុរេ ថ្នាក់ទី៩ (ពីមេរៀនថ្នាក់ទី៨) — ៦០ នាទី'), 11, 'ចងការប្រាក់ \(2\,000\,000\) ៛ អត្រា \(15\%\) ក្នុងមួយឆ្នាំ។ ការប្រាក់ \(3\) ឆ្នាំ៖', NULL, '["\\(900\\,000\\) ៛", "\\(450\\,000\\) ៛", "\\(2\\,900\\,000\\) ៛", "\\(300\\,000\\) ៛"]', 0, NULL, 2, 'mcq', '\(\dfrac{2\,000\,000 \times 15 \times 3}{100} = 900\,000\)។', 'ទំហំសមាមាត្រនិងភាគរយ', 'medium', 1, '8', 'ទំហំសមាមាត្រនិងភាគរយ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES ((SELECT MAX(id) FROM tests WHERE title = 'តេស្តបុរេ ថ្នាក់ទី៩ (ពីមេរៀនថ្នាក់ទី៨) — ៦០ នាទី'), 12, 'ត្រីកោណកែង \(ABC\) កែងត្រង់ \(A\) មាន \(BC = 15\ \text{cm}\) និង \(AB = 9\ \text{cm}\)។ គណនា \(AC\)។', NULL, '["\\(6\\ \\text{cm}\\)", "\\(10\\ \\text{cm}\\)", "\\(16\\ \\text{cm}\\)", "\\(12\\ \\text{cm}\\)"]', 3, NULL, 2, 'mcq', '\(AC = \sqrt{BC^2 - AB^2} = \sqrt{225 - 81} = \sqrt{144} = 12\ \text{cm}\)', 'ទ្រឹស្តីបទពីតាក័រ', 'easy', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES ((SELECT MAX(id) FROM tests WHERE title = 'តេស្តបុរេ ថ្នាក់ទី៩ (ពីមេរៀនថ្នាក់ទី៨) — ៦០ នាទី'), 13, 'ចតុកោណស្មើមួយមានអង្កត់ទ្រូងទាំងពីរប្រវែង \(16\ \text{cm}\) និង \(12\ \text{cm}\)។ គណនាប្រវែងជ្រុងនៃចតុកោណស្មើ។', NULL, '["\\(20\\ \\text{cm}\\)", "\\(14\\ \\text{cm}\\)", "\\(10\\ \\text{cm}\\)", "\\(8\\ \\text{cm}\\)"]', 2, NULL, 2, 'mcq', 'អង្កត់ទ្រូងចតុកោណស្មើកាត់គ្នាកែងត្រង់ចំណុចកណ្តាល ៖ \(a = \sqrt{8^2 + 6^2} = \sqrt{64 + 36} = 10\ \text{cm}\)', 'ទ្រឹស្តីបទពីតាក័រ', 'medium', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES ((SELECT MAX(id) FROM tests WHERE title = 'តេស្តបុរេ ថ្នាក់ទី៩ (ពីមេរៀនថ្នាក់ទី៨) — ៦០ នាទី'), 14, 'ក្នុងត្រីកោណទាលមួយ (មានមុំមួយធំជាង \(90^\circ\)) តើអរតូសង់ \(H\) ស្ថិតនៅទីណា?', NULL, '["នៅខាងក្រៅត្រីកោណ", "នៅលើជ្រុងវែងជាងគេ", "ត្រង់កំពូលនៃមុំទាល", "នៅខាងក្នុងត្រីកោណ"]', 0, NULL, 2, 'mcq', 'ក្នុងត្រីកោណទាល កម្ពស់ទាំងបីប្រសព្វគ្នានៅខាងក្រៅត្រីកោណ', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', 'medium', 1, '8', 'បន្ទាត់និងអង្កត់ពិសេសជួបគ្នានៅក្នុងត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES ((SELECT MAX(id) FROM tests WHERE title = 'តេស្តបុរេ ថ្នាក់ទី៩ (ពីមេរៀនថ្នាក់ទី៨) — ៦០ នាទី'), 15, 'គេបោះគ្រាប់ឡុកឡាក់មួយគ្រាប់។ ប្រូបាបដែលបោះបានលេខធំជាង ៣ គឺ ៖', NULL, '["\\(\\dfrac{1}{2}\\)", "\\(\\dfrac{1}{3}\\)", "\\(\\dfrac{5}{6}\\)", "\\(\\dfrac{2}{3}\\)"]', 0, NULL, 2, 'mcq', 'លេខធំជាង ៣ មាន ៣ គឺ \(\{4, 5, 6\}\) នាំឱ្យ \(P = \dfrac{3}{6} = \dfrac{1}{2}\)។', 'ប្រូបាប', 'medium', 1, '8', 'ប្រូបាប', NULL, 0);
